<?php
declare(strict_types=1);
require_once __DIR__.'/stock-flow.php';require_once __DIR__.'/workbook-lib.php';require_once __DIR__.'/report-dates.php';require_once __DIR__.'/board-products.php';
function stock_schema(PDO $db): void {$db->exec("CREATE TABLE IF NOT EXISTS stock_products(sku TEXT PRIMARY KEY,name TEXT NOT NULL,gender TEXT NOT NULL);CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,request_key TEXT NOT NULL UNIQUE,sku TEXT NOT NULL,size TEXT NOT NULL,kind TEXT NOT NULL,quantity INTEGER NOT NULL,note TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL)");}
function board_catalog(PDO $db): array {
 stock_schema($db);$products=[];$path=dirname(__DIR__).'/catalog.js';
 if(is_file($path)){$text=file_get_contents($path);if(preg_match('/\b(?:const|let|var)\s+products\s*=\s*\[/',$text,$m,PREG_OFFSET_CAPTURE)){$start=$m[0][1]+strlen($m[0][0])-1;$depth=0;$quoted=false;$escaped=false;for($i=$start,$n=strlen($text);$i<$n;$i++){$ch=$text[$i];if($quoted){if($escaped)$escaped=false;elseif($ch==='\\')$escaped=true;elseif($ch==='"')$quoted=false;continue;}if($ch==='"'){$quoted=true;continue;}if($ch==='[')$depth++;elseif($ch===']'&&--$depth===0){$products=json_decode(substr($text,$start,$i-$start+1),true)??[];break;}}}}
 $result=[];foreach($products as $p){$sku=mb_strtoupper(trim((string)($p['sku']??'')),'UTF-8');if($sku!=='')$result[$sku]=['sku'=>$sku,'name'=>(string)($p['name']??$sku),'gender'=>in_array($p['gender']??'',['Nam','Nữ'],true)?$p['gender']:'','sizes'=>array_values(array_filter((array)($p['sizes']??[]),'is_string'))];}
 foreach($db->query('SELECT * FROM stock_products') as $p)$result[$p['sku']]??=['sku'=>$p['sku'],'name'=>$p['name'],'gender'=>$p['gender']];if(function_exists('stats_catalog')){try{$live=stats_catalog();foreach(($live['products']??[]) as $product){$sku=mb_strtoupper(trim((string)($product['sku']??'')),'UTF-8');if(isset($result[$sku])&&is_numeric($product['price']??null)&&(float)$product['price']>0)$result[$sku]['price']=(float)$product['price'];}}catch(Throwable $e){/* Missing catalog prices stay unknown; no invented revenue allocation. */}}ksort($result);return $result;
}
function board_rows(PDO $db,array $catalog): array {
 wb_schema($db);$db->exec('CREATE TABLE IF NOT EXISTS workbook_sheet_years(sheet_id TEXT PRIMARY KEY,year INTEGER NOT NULL)');$yearFind=$db->prepare('SELECT year FROM workbook_sheet_years WHERE sheet_id=?');$yearSave=$db->prepare('INSERT OR IGNORE INTO workbook_sheet_years(sheet_id,year) VALUES(?,?)');$current=wb_current($db);$rows=[];$issues=[];
 foreach(($current['snapshot']['sheetOrder']??[]) as $id){$sheet=$current['snapshot']['sheets'][$id];$name=report_fold((string)$sheet['name']);if(in_array($name,['BANG HEN GIAO','DON BUU DIEN'],true))continue;$yearFind->execute([$id]);$year=$yearFind->fetchColumn();if($year===false){$year=(int)(new DateTimeImmutable('now',new DateTimeZone('Asia/Ho_Chi_Minh')))->format('Y');$yearSave->execute([$id,$year]);}$info=report_sheet_info((string)$sheet['name'],(int)$year);$map=[];foreach(($sheet['cellData'][0]??[]) as $c=>$cell)$map[report_fold((string)($cell['v']??''))]=(int)$c;$product=$map['SAN PHAM / SIZE']??$map['SAN PHAM']??null;if($product===null)continue;$created=$map['TAO DON']??null;$sheetWarnings=[];if(!$info['date'])$sheetWarnings[]='Sheet chưa có ngày để thống kê';if(!$info['gender'])$sheetWarnings[]='Sheet chưa ghi NAM hoặc NỮ; chưa phân nhóm đơn';if($sheetWarnings)$issues[]=['sheet'=>$sheet['name'],'row'=>1,'date'=>$info['date'],'gender'=>$info['gender'],'text'=>'','kind'=>'sheet','errors'=>$sheetWarnings];
  foreach(($sheet['cellData']??[]) as $r=>$cells){if((int)$r<1)continue;$value=trim((string)($cells[$product]['v']??''));if($value==='')continue;$parsed=board_lines($value,$catalog);$genderErrors=board_gender_errors($parsed,$info['gender']);$errors=array_merge($parsed['errors'],$genderErrors);if($errors)$issues[]=['sheet'=>$sheet['name'],'row'=>(int)$r+1,'date'=>$info['date'],'gender'=>$info['gender'],'text'=>$value,'kind'=>$genderErrors?'gender':'product','errors'=>$errors];$returned=$map['HOAN']??null;$rows[]=['rowId'=>(string)($cells[0]['custom']['victorRowId']??''),'measurements'=>(string)($cells[$map['CHIEU CAO / CAN NANG']??$map['CHIEU CAO/CAN NANG']??-1]['v']??''),'status'=>(string)($cells[$map['TINH TRANG']??-1]['v']??''),'sheetId'=>$id,'tracking'=>trim((string)($cells[$map['MA VAN DON']??-1]['v']??'')),'money'=>$cells[$map['TIEN']??-1]['v']??null,'sheet'=>$sheet['name'],'row'=>(int)$r+1,'text'=>$value,'date'=>$info['date'],'gender'=>$info['gender'],'returned'=>$returned!==null&&trim((string)($cells[$returned]['v']??''))!==''&&!in_array(report_fold((string)($cells[$returned]['v']??'')),['0','FALSE','NO','KHONG','CHUA'],true),'created'=>$created!==null&&trim((string)($cells[$created]['v']??''))!=='','items'=>$parsed['items'],'incoming'=>$parsed['incoming'],'exchange'=>$parsed['exchange'],'valid'=>!$parsed['errors']];}
 }return ['rows'=>$rows,'issues'=>$issues,'version'=>$current['version']??0];
}
function board_report(PDO $db,array $input): array {
 team_require_owner();$range=report_range($input);$gender=(string)($input['gender']??'');if(!in_array($gender,['','Nam','Nữ'],true))throw new RuntimeException('Nhóm báo cáo không hợp lệ.',400);$sku=mb_strtoupper(trim((string)($input['sku']??'')),'UTF-8');$size=mb_strtoupper(trim((string)($input['size']??'')),'UTF-8');$catalog=board_catalog($db);$board=board_rows($db,$catalog);$total=0;$created=0;$returned=0;$qty=0;$sales=[];$exchanges=[];
 foreach($board['rows'] as $row){if(!$row['date']||$row['date']<$range['from']||$row['date']>$range['to']||($gender!==''&&$row['gender']!==$gender))continue;$items=array_values(array_filter($row['items'],static fn($i)=>($sku===''||$i['sku']===$sku)&&($size===''||$i['size']===$size)));if(($sku!==''||$size!=='')&&!$items)continue;$total++;if($row['exchange'])$exchanges[]=$row;if(!$row['created'])continue;$created++;if($row['returned'])$returned++;foreach($items as $i){$key=$i['sku'].'|'.$i['size'];if(!isset($sales[$key]))$sales[$key]=$i+['quantity'=>0];$sales[$key]['quantity']+=$i['qty'];$qty+=$i['qty'];}}
 return ['range'=>$range,'orders'=>$total,'created'=>$created,'returned'=>$returned,'returnRate'=>$created>0?round($returned*100/$created,2):0,'quantity'=>$qty,'sales'=>array_values($sales),'exchanges'=>$exchanges,'issues'=>array_values(array_filter($board['issues'],static fn($i)=>($i['date']===''||($i['date']>=$range['from']&&$i['date']<=$range['to']))&&($gender===''||$i['gender']===$gender))),'version'=>$board['version'],'catalog'=>array_values($catalog)];
}
function stock_balances(PDO $db): array {
 $catalog=board_catalog($db);$board=board_rows($db,$catalog);$balances=[];$ensure=static function(string $sku,string $size)use(&$balances,$catalog):string{$key=$sku.'|'.$size;if(!isset($balances[$key]))$balances[$key]=['sku'=>$sku,'size'=>$size,'name'=>$catalog[$sku]['name']??$sku,'gender'=>$catalog[$sku]['gender']??'','received'=>0,'returned'=>0,'adjustment'=>0,'sold'=>0,'balance'=>0];return $key;};
 foreach($db->query('SELECT sku,size,kind,SUM(quantity) AS qty FROM stock_movements GROUP BY sku,size,kind') as $m){$key=$ensure($m['sku'],$m['size']);$field=['receipt'=>'received','return'=>'returned','adjust'=>'adjustment'][$m['kind']]??'adjustment';$balances[$key][$field]+=(int)$m['qty'];}
 $flow=stock_flow($db,$board['rows']);foreach($flow['totals'] as $pair=>$totals){[$sku,$size]=explode('|',$pair,2);$key=$ensure($sku,$size);foreach($totals as $field=>$qty)$balances[$key][$field]=$qty;}foreach($balances as &$b){$b+=['shipping'=>0,'returning'=>0,'autoReturned'=>0];$b['returned']+=$b['autoReturned'];$b['balance']=$b['received']+$b['returned']+$b['adjustment']-$b['sold'];}unset($b);ksort($balances);return ['balances'=>array_values($balances),'returnCases'=>$flow['cases'],'catalog'=>array_values($catalog),'issues'=>$board['issues'],'version'=>$board['version']];
}
function stock_view(PDO $db): array {team_require_owner();$result=stock_balances($db);$result['movements']=$db->query('SELECT * FROM stock_movements ORDER BY id DESC LIMIT 100')->fetchAll();return $result;}
function stock_save(PDO $db,array $input): array {
 team_require_owner();stock_schema($db);$sku=mb_strtoupper(trim((string)($input['sku']??'')),'UTF-8');$size=mb_strtoupper(trim((string)($input['size']??'')),'UTF-8');$kind=$input['kind']??'';$qty=$input['quantity']??null;$note=trim((string)($input['note']??''));$key=$input['request_key']??'';if(!preg_match('/^[A-Z0-9][A-Z0-9._-]{0,39}$/D',$sku)||!preg_match('/^[A-Z0-9 -]{1,20}$/D',$size)||!in_array($kind,['receipt','return','stocktake'],true)||!is_int($qty)||$qty<0||$qty>1000000||($kind!=='stocktake'&&$qty===0)||strlen($note)>2000||!is_string($key)||!preg_match('/^[a-f0-9-]{36}$/D',$key))throw new RuntimeException('Kiểm tra mã, size, số lượng và ghi chú.',400);
 $db->exec('BEGIN IMMEDIATE');try{$q=$db->prepare('SELECT * FROM stock_movements WHERE request_key=?');$q->execute([$key]);$old=$q->fetch();if($old){if($old['sku']!==$sku||$old['size']!==$size||($kind!=='stocktake'&&((int)$old['quantity']!==$qty||$old['kind']!==$kind)))throw new RuntimeException('Mã yêu cầu kho đã được dùng cho dữ liệu khác. Làm mới trước khi thử lại.',409);$db->exec('COMMIT');return ['ok'=>true,'already'=>true,'id'=>(int)$old['id']];}$catalog=board_catalog($db);if(!isset($catalog[$sku])){$name=trim((string)($input['name']??$sku));$gender=$input['gender']??'';if($name===''||mb_strlen($name)>150||!in_array($gender,['Nam','Nữ'],true))throw new RuntimeException('Mã mới cần tên sản phẩm và nhóm Nam/Nữ.',400);$db->prepare('INSERT INTO stock_products(sku,name,gender) VALUES(?,?,?)')->execute([$sku,$name,$gender]);}
 $amount=$qty;$storedKind=$kind;if($kind==='stocktake'){$balance=0;foreach(stock_balances($db)['balances'] as $b)if($b['sku']===$sku&&$b['size']===$size)$balance=$b['balance'];$amount=$qty-$balance;$storedKind='adjust';$note='Kiểm kê tồn thực tế '.$qty.'. '.$note;}$actor=team_identity()['username'];$db->prepare('INSERT INTO stock_movements(request_key,sku,size,kind,quantity,note,actor,created_at) VALUES(?,?,?,?,?,?,?,?)')->execute([$key,$sku,$size,$storedKind,$amount,$note,$actor,gmdate('c')]);$id=(int)$db->lastInsertId();people_audit('stock_'.$kind,$sku.' / '.$size,['quantity'=>$amount,'note'=>$note],$db);$db->exec('COMMIT');return ['ok'=>true,'id'=>$id];}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}
